import json
import os
import shlex
import subprocess
import sys

from typer.testing import CliRunner

from cartage.cli import app

runner = CliRunner()
DAG = "dags/materials.py"


def cli(project, *args):
    return runner.invoke(app, ["-C", str(project), *args])


def generate(project):
    result = cli(project, "generate")
    assert result.exit_code == 0, result.output
    return (project / DAG).read_text()


def test_generates_valid_thin_dag(project):
    content = generate(project)
    compile(content, DAG, "exec")
    assert content.startswith(
        "# Generated by cartage 0.8.1 from pipelines/materials.yaml"
    )
    assert "from airflow.decorators import dag, task" in content
    assert "@dag(\n" in content and "def materials():" in content
    assert content.rstrip().endswith("materials()")
    assert "    @task.bash\n    def cartage_run():" in content
    assert "dag_id='materials'" in content
    assert "schedule='0 3 * * *'" in content
    assert "tags=['cartage']" in content
    assert "default_args = {'owner': 'data-team', 'retries': 1}" in content
    assert (
        """return 'cartage' + " --project-dir " + shlex.quote(PROJECT_DIR) + " run " + """
        """"pipelines/materials.yaml --env {{ var.value.get('cartage_env', 'prd') }}"\n"""
    ) in content
    assert "os.path.dirname(__file__), '..'" in content
    assert "k8s" not in content


def test_generation_is_deterministic(project):
    assert generate(project) == generate(project)


def test_settings_merge_image_and_custom_decorator(project):
    settings = project / "cartage.yaml"
    settings.write_text(
        settings.read_text().replace(
            "    dags_dir: dags\n",
            "    dags_dir: dags\n    task_decorator: datacoves_bash\n    operator_args: { retries: 2, pool: default }\n",
        )
    )
    pipeline = project / "pipelines/materials.yaml"
    pipeline.write_text(
        pipeline.read_text().replace(
            '    schedule: "0 3 * * *"\n',
            '    schedule: "0 3 * * *"\n' "    image: reg/cartage:1\n    operator_args: { pool: sap }\n",
        )
    )
    content = generate(project)
    compile(content, DAG, "exec")
    assert "    @task.datacoves_bash(\n" in content
    assert "pool='sap'," in content and "retries=2," in content
    assert "from kubernetes.client import models as k8s" in content
    assert "image='reg/cartage:1'" in content


def test_project_template_override_extends_blocks(project):
    (project / "templates/airflow").mkdir(parents=True)
    (project / "templates/airflow/dag.py.j2").write_text(
        '{% extends "cartage/airflow_dag.py.j2" %}\n{% block extra %}\n# custom footer for {{ dag_id }}\n{% endblock %}\n'
    )
    content = generate(project)
    compile(content, DAG, "exec")
    assert content.rstrip().endswith("# custom footer for materials")


def test_sink_pipelines_need_remote_state_on_the_orchestrator(project):
    config = project / "cartage.yaml"
    config.write_text(config.read_text().replace("prd: {connection: landing, prefix: cartage/state/}",
                                                 "prd: {path: .cartage/state}"))
    result = cli(project, "generate")
    assert result.exit_code == 2
    assert "env 'prd' keeps that state on local disk" in result.output


def test_check_detects_stale_files(project):
    generate(project)
    assert cli(project, "generate", "--check").exit_code == 0
    (project / DAG).write_text("# edited by hand\n")
    stale = cli(project, "generate", "--check")
    assert stale.exit_code == 1
    assert "materials.py" in stale.output


def test_show_context(project):
    result = cli(project, "generate", "--show-context", "materials")
    assert result.exit_code == 0, result.output
    assert json.loads(result.output)["dag_id"] == "materials"


def test_unknown_setting_is_rejected(project):
    pipeline = project / "pipelines/materials.yaml"
    pipeline.write_text(
        pipeline.read_text().replace(
            '    schedule: "0 3 * * *"\n', '    schedule: "0 3 * * *"\n' "    imgae: x\n"
        )
    )
    result = cli(project, "generate")
    assert result.exit_code == 2
    assert "Unknown Airflow setting(s): imgae" in result.output


def _edit_pipeline(project, extra):
    pipeline = project / "pipelines/materials.yaml"
    pipeline.write_text(
        pipeline.read_text().replace(
            '    schedule: "0 3 * * *"\n', '    schedule: "0 3 * * *"\n' + extra
        )
    )


def test_invalid_operator_args_keys_rejected(project):
    for key in ("pool-x", "task_id"):
        _edit_pipeline(project, f"    operator_args: {{ {key}: 1 }}\n")
        result = cli(project, "generate")
        assert result.exit_code == 2
        assert "Invalid Airflow operator_args key" in result.output
        _edit_pipeline(project, "")  # no-op; file reset below
        (project / "pipelines/materials.yaml").write_text(
            (project / "pipelines/materials.yaml")
            .read_text()
            .replace(f"    operator_args: {{ {key}: 1 }}\n", "")
        )


