def test_dependencies_add_up_and_become_uv_with_flags(project):
    settings = project / "cartage.yaml"
    settings.write_text(settings.read_text().replace(
        "    dags_dir: dags\n",
        '    dags_dir: dags\n    command: uvx --from "cartage>=0.7" cartage\n    dependencies: ["dlt[snowflake]", pandas]\n'))
    _edit_pipeline(project, "    dependencies: [pandas, pyarrow]\n")
    content = generate(project)
    compile(content, DAG, "exec")
    assert "return \"uvx --with 'dlt[snowflake]' --with pandas --with pyarrow --from 'cartage>=0.7' cartage\" + " in content


def test_dependencies_need_a_uv_command(project):
    _edit_pipeline(project, "    dependencies: [pandas]\n")
    result = cli(project, "generate")
    assert result.exit_code == 2
    assert "Airflow dependencies need a uv command" in result.output


def test_default_args_and_schedule_from_functions(project):
    _edit_pipeline(project, "    default_args_from: utils.dags:set_default_args\n"
                            "    default_args: { owner: Ana, owner_email: ana@example.com }\n"
                            "    schedule_from: utils.dags:set_schedule\n")
    content = generate(project)
    compile(content, DAG, "exec")
    assert "from utils.dags import set_default_args\nfrom utils.dags import set_schedule\n" in content
    # project default_args (owner, retries) merge with the pipeline's, then become keyword arguments
    assert "default_args = set_default_args(owner='Ana', retries=1, owner_email='ana@example.com')\n" in content
    assert "    schedule=set_schedule('0 3 * * *'),\n" in content


def test_invalid_function_reference_rejected(project):
    _edit_pipeline(project, "    schedule_from: utils.set_schedule\n")
    result = cli(project, "generate")
    assert result.exit_code == 2
    assert "must be 'module.path:function'" in result.output


def test_dag_function_name_is_a_python_identifier(project):
    _edit_pipeline(project, "    dag_id: 1-materials.sap\n")
    result = cli(project, "generate")
    assert result.exit_code == 0, result.output
    content = (project / "dags/1-materials.sap.py").read_text()
    compile(content, "dag", "exec")
    assert "def _1_materials_sap():" in content and "dag_id='1-materials.sap'" in content
